#!/usr/bin/env node
/**
 * What's inside each JS chunk: generated bytes attributed to source files through the source
 * maps of a `--sourcemap` build (node_modules/.cache/settle-bench/dist-sm, made by `node bench/profile.mjs --sourcemap`
 * or `vite build --sourcemap --outDir node_modules/.cache/settle-bench/dist-sm/client`).
 *
 *   node bench/composition.mjs [--dist node_modules/.cache/settle-bench/dist-sm] [--chunk index] [--top 30]
 */
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { parseArgs } from 'node:util'
import { TraceMap, eachMapping } from '@jridgewell/trace-mapping'
import { CACHE_DIR } from './lib/paths.mjs'

const { values: args } = parseArgs({
  options: {
    dist: { type: 'string', default: join(CACHE_DIR, 'dist-sm') },
    chunk: { type: 'string' },
    top: { type: 'string', default: '30' },
  },
})

const assets = join(args.dist, 'client', 'assets')
const html = readFileSync(join(args.dist, 'client', 'index.html'), 'utf8')
const upfront = new Set([...html.matchAll(/(?:src|href)="\/assets\/([^"]+\.js)"/g)].map((m) => m[1]))

function shortSource(source) {
  const s = source.replace(/\\/g, '/')
  const nm = s.lastIndexOf('/node_modules/')
  if (nm !== -1) {
    const rest = s.slice(nm + 14).split('/')
    return `npm:${rest[0].startsWith('@') ? `${rest[0]}/${rest[1]}` : rest[0]}`
  }
  const src = s.indexOf('src/')
  return src !== -1 ? s.slice(src) : s.replace(/^(\.\.\/)+/, '')
}

for (const file of readdirSync(assets).filter((f) => f.endsWith('.js')).sort()) {
  if (args.chunk && !file.startsWith(args.chunk)) continue
  const code = readFileSync(join(assets, file), 'utf8')
  const map = new TraceMap(JSON.parse(readFileSync(join(assets, `${file}.map`), 'utf8')))
  const lines = code.split('\n')
  const bySource = new Map()
  let previous = null
  const credit = (m, endColumn) => {
    const line = lines[m.generatedLine - 1] ?? ''
    const bytes = Math.max(0, Math.min(endColumn, line.length) - m.generatedColumn)
    const key = m.source ? shortSource(m.source) : '(generated)'
    bySource.set(key, (bySource.get(key) ?? 0) + bytes)
  }
  eachMapping(map, (m) => {
    if (previous && previous.generatedLine === m.generatedLine) credit(previous, m.generatedColumn)
    else if (previous) credit(previous, Infinity)
    previous = m
  })
  if (previous) credit(previous, Infinity)
  const total = code.length
  const rows = [...bySource.entries()].sort((a, b) => b[1] - a[1])
  // Group by package / folder for the summary line.
  const groups = new Map()
  for (const [source, bytes] of rows) {
    const key = source.startsWith('npm:') ? source : source.split('/').slice(0, 2).join('/')
    groups.set(key, (groups.get(key) ?? 0) + bytes)
  }
  console.log(`\n## ${file}${upfront.has(file) ? '  [loaded up front]' : ''} — ${(total / 1024).toFixed(1)} KB`)
  console.log(
    [...groups.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 12)
      .map(([k, v]) => `${k} ${(v / 1024).toFixed(1)}K`)
      .join(' · '),
  )
  if (args.chunk) for (const [source, bytes] of rows.slice(0, Number(args.top))) console.log(`${(bytes / 1024).toFixed(1).padStart(8)} KB  ${source}`)
}
